#include <locale>
#include <iostream>
int main() {
    // Create a base locale object
    std::locale base_locale("en_US.UTF-8");
    // Create a new locale by copying 'base_locale' and modifying its name and category
    std::locale custom_locale(base_locale, "fr_FR.UTF-8", std::locale::ctype);
    // Use the custom locale to imbue a stream
    std::cout.imbue(custom_locale);
    std::cout << "Locale customized to French UTF-8." << std::endl;
    return 0;
}
